def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Matching diagonal neighbors define a ray continuing from the lower
    # member of the pair in that diagonal direction.
    for r in range(h - 1):
        for c in range(w):
            color = grid[r][c]
            if color == 0:
                continue
            for dc in (-1, 1):
                c2 = c + dc
                if 0 <= c2 < w and grid[r + 1][c2] == color:
                    rr, cc = r + 2, c2 + dc
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == 0:
                        out[rr][cc] = color
                        rr += 1
                        cc += dc
    return out
